protected function ensureOrderForCursorPagination($shouldReverse = false)
{
    if (empty($this->query->orders) && empty($this->query->unionOrders)) {
        $this->enforceOrderBy();
    }

    $reverseDirection = function ($order) {
        if (! isset($order['direction'])) {
            return $order;
